import 'server-only'

import type { PoolClient } from 'pg'

import { runGreenhousePostgresQuery } from '@/lib/postgres/client'

/**
 * Data access of the quoter registry (TASK-2025).
 *
 * Every store receives the client of the transaction it runs in, so a row, its history and its outbox event are
 * written together or not at all. Nothing here opens a connection: the pool lives in `src/lib/postgres/client.ts`.
 *
 * SQL is written by hand on purpose. `src/types/db.d.ts` is generated by reading the live database, so it knows
 * nothing about `quoter_*` until the migrations are applied; and a client that is only `{ query }` lets the tests
 * hand in a connection to the local cluster. Every statement here is exercised against real PostgreSQL by
 * `pnpm quoter:test:local`: a mock proves the TypeScript, never the SQL.
 */
export type QuoterDbClient = Pick<PoolClient, 'query'>

/** With a client, inside its transaction; without one, a single statement on the canonical pool (reads only). */
export const runQuoterQuery = async <T extends Record<string, unknown>>(
  client: QuoterDbClient | undefined,
  sql: string,
  params: unknown[] = []
): Promise<T[]> => {
  if (client) {
    const result = await client.query<T>(sql, params)

    return result.rows
  }

  return runGreenhousePostgresQuery<T>(sql, params)
}

/** The SQLSTATE of a rejected statement, when the driver reports one. */
export const sqlStateOf = (error: unknown): string | undefined => {
  const code = (error as { code?: unknown } | null)?.code

  return typeof code === 'string' ? code : undefined
}

/** The constraint a rejected statement names, when the driver reports one. */
export const constraintOf = (error: unknown): string | undefined => {
  const constraint = (error as { constraint?: unknown } | null)?.constraint

  return typeof constraint === 'string' ? constraint : undefined
}

export const UNIQUE_VIOLATION = '23505'
export const FOREIGN_KEY_VIOLATION = '23503'
export const CHECK_VIOLATION = '23514'

export const toIso = (value: unknown): string => (value instanceof Date ? value.toISOString() : String(value))
